import type { Source } from "./Core";
/**
 * Convert an array to a callbag pullable source. Data
 * will only be sent when requested.
 *
 * Adapted from https://github.com/staltz/callbag-from-iter
 *
 * Marble diagram:
 *   {fromIter([a,b,c])}
 *   " a b c |"
 *
 * @param iterable The iterable to iterate over.
 * @returns A callbag source that emits for each element
 *     in the iterable.
 *
 * @internal
 */
export declare const fromIter: <T>(iterable: Iterable<T>) => Source<T, never>;
